pub struct Frame {
    pub kind: u8,
    pub len: u16,
    pub body: Vec<u8>,
}

pub fn parse(buf: &[u8]) -> Frame {
    let kind = buf[0];
    let len = u16::from_be_bytes([buf[1], buf[2]]);
    let body = buf[3..3 + len as usize].to_vec();
    Frame { kind, len, body }
}

